class Solution {
public:
    int amountOfTime(TreeNode* root, int start) {
        std::unordered_map<int, std::vector<int>> adj;
        std::function<void(TreeNode*, TreeNode*)> build = [&](TreeNode* node, TreeNode* parent) {
            if (!node) return;
            if (parent) {
                adj[node->val].push_back(parent->val);
                adj[parent->val].push_back(node->val);
            }
            build(node->left, node);
            build(node->right, node);
        };
        build(root, nullptr);

        std::queue<int> q;
        std::unordered_set<int> visited;
        q.push(start);
        visited.insert(start);
        int minutes = -1;

        while (!q.empty()) {
            int sz = q.size();
            for (int i = 0; i < sz; i++) {
                int curr = q.front();
                q.pop();
                for (int nxt : adj[curr]) {
                    if (!visited.count(nxt)) {
                        visited.insert(nxt);
                        q.push(nxt);
                    }
                }
            }
            minutes++;
        }
        return std::max(0, minutes);
    }
};

class Solution {
    public int amountOfTime(TreeNode root, int start) {
        java.util.Map<Integer, java.util.List<Integer>> adj = new java.util.HashMap<>();
        buildGraph(root, null, adj);

        java.util.Queue<Integer> q = new java.util.LinkedList<>();
        java.util.Set<Integer> visited = new java.util.HashSet<>();
        q.offer(start);
        visited.add(start);
        int minutes = -1;

        while (!q.isEmpty()) {
            int sz = q.size();
            for (int i = 0; i < sz; i++) {
                int curr = q.poll();
                for (int neighbor : adj.getOrDefault(curr, java.util.Collections.emptyList())) {
                    if (!visited.contains(neighbor)) {
                        visited.add(neighbor);
                        q.offer(neighbor);
                    }
                }
            }
            minutes++;
        }
        return Math.max(0, minutes);
    }

    private void buildGraph(TreeNode node, TreeNode parent, java.util.Map<Integer, java.util.List<Integer>> adj) {
        if (node == null) return;
        if (parent != null) {
            adj.computeIfAbsent(node.val, k -> new java.util.ArrayList<>()).add(parent.val);
            adj.computeIfAbsent(parent.val, k -> new java.util.ArrayList<>()).add(node.val);
        }
        buildGraph(node.left, node, adj);
        buildGraph(node.right, node, adj);
    }
}

var amountOfTime = function(root, start) {
    const adj = new Map();
    function build(node, parent) {
        if (!node) return;
        if (!adj.has(node.val)) adj.set(node.val, []);
        if (parent) {
            adj.get(node.val).push(parent.val);
            if (!adj.has(parent.val)) adj.set(parent.val, []);
            adj.get(parent.val).push(node.val);
        }
        build(node.left, node);
        build(node.right, node);
    }
    build(root, null);

    const q = [start];
    const visited = new Set([start]);
    let minutes = -1;

    while (q.length > 0) {
        const sz = q.length;
        for (let i = 0; i < sz; i++) {
            const curr = q.shift();
            for (const neighbor of (adj.get(curr) || [])) {
                if (!visited.has(neighbor)) {
                    visited.add(neighbor);
                    q.push(neighbor);
                }
            }
        }
        minutes++;
    }
    return Math.max(0, minutes);
};
